window.MOTIF_CATALOG_CHUNKS[109]={"cards":[{"id":"MEJE-KW-011034","row_version":2,"title":"무작위 결과를 넣은 게임 규칙","original":"Gameplay Randomization","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임이 주사위나 카드, 난수 등을 통해 같은 선택에서도 다른 결과가 나올 수 있게 설계한다. 무작위 보상을 반복해 뽑는 무작위 뽑기 중심 게임은 확률 규칙을 수익 구조와 결합한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-011034/index.html"},{"id":"MEJE-KW-011035","row_version":2,"title":"계속 바뀌는 플레이 방식","original":"Gameplay Roulette","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"한 게임이나 시리즈가 구간마다 조작과 핵심 규칙을 크게 바꿔 여러 장르를 오가듯 진행된다. 플레이 방식이 바뀌는 것과 플레이어의 조작을 아예 맡아 버리는 게임이 플레이를 대신하다은 구별된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-011035/index.html"},{"id":"MEJE-KW-011036","row_version":1,"title":"게임이 플레이를 대신하다","original":"Game Plays Itself","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"같은 장르라면 보통 플레이어가 직접 할 행동을 게임이 강제로 자동 처리하거나 영상으로 넘겨 조작 기회를 빼앗는다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-011036/index.html"},{"id":"MEJE-KW-011037","row_version":1,"title":"게임을 잘하는 여성 인물","original":"Gamer Chick","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 여성 게이머의 실력을 주변의 낮은 기대와 대비시켜 놀라움이나 반격의 장면으로 만드는 재현 관습이다. 게임 실력은 성별로 정해지지 않는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011037/index.html"},{"id":"MEJE-KW-011038","row_version":6,"title":"경품을 놓고 겨루는 방송","original":"Game Show","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04"],"summary":"참가자가 문제나 과제를 수행하고 상금이나 물건을 받는 경쟁을 방송의 중심에 둔 프로그램 형식이다. 경품 경연 방송에 극중 인물이 참여하면 퀴즈 방송에 출연한 인물이 된다. 방송 참가자의 엉뚱한 모습으로 웃음을 내면 엉뚱한 참가자들의 게임쇼와 이어진다. 방송의 규칙과 분위기를 이끄는 인물은 게임쇼 진행자다. 퀴즈 대신 몸으로 경쟁하는 구간은 몸으로 겨루는 방송 과제으로 꾸릴 수 있다. 방송 운영 규칙에 경품의 상한을 두면 게임쇼 상금의 상한선이 된다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"분류축","entry_url":"cards/MEJE-KW-011038/index.html"},{"id":"MEJE-KW-011039","row_version":1,"title":"퀴즈 방송에 출연한 인물","original":"Game Show Appearance","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"작품 속 인물이 퀴즈나 경품을 다루는 방송 프로그램에 출연하는 이야기 장치. 출연 자체가 핵심이며 실수나 경쟁은 그 뒤에 붙을 수 있는 사건이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-011039/index.html"},{"id":"MEJE-KW-011040","row_version":1,"title":"엉뚱한 참가자들의 게임쇼","original":"Game Show Goofballs","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 경연 방송의 출연자들에게 과장된 오답과 기행을 맡겨 프로그램 자체를 희극적으로 그리는 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011040/index.html"},{"id":"MEJE-KW-011041","row_version":1,"title":"게임쇼 진행자","original":"Game Show Host","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"참가자를 소개하고 규칙과 결과를 전달하며 방송의 분위기를 이끄는 진행자 인물형이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-011041/index.html"},{"id":"MEJE-KW-011042","row_version":1,"title":"몸으로 겨루는 방송 과제","original":"Game Show Physical Challenge","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"경쟁 방송에서 참가자의 힘과 지구력, 민첩성을 시험하는 과제를 볼거리의 중심에 놓는 구성이다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-011042/index.html"},{"id":"MEJE-KW-011043","row_version":1,"title":"게임쇼 상금의 상한선","original":"Game Show Winnings Cap","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"방송이 한 참가자가 받을 수 있는 경품의 총액이나 연속 출연 횟수에 제한을 두는 운영 규칙이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-011043/index.html"},{"id":"MEJE-KW-011044","row_version":1,"title":"노인의 놀이로 여겨지는 게임","original":"Games of the Elderly","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이나 사회가 특정 놀이를 노년층의 취미로 묶어 묘사하는 관습이다. 실제 참여자의 나이는 지역과 문화에 따라 다르다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011044/index.html"},{"id":"MEJE-KW-011045","row_version":1,"title":"역할놀이의 규칙 체계","original":"Game System","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"탁상 역할놀이에서 인물이 할 수 있는 행동과 그 결과를 판정하기 위해 정한 능력치와 절차의 묶음이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-011045/index.html"},{"id":"MEJE-KW-011046","row_version":1,"title":"게임 안에서 플레이하는 게임","original":"Game Within a Game","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"비디오게임의 세계 안에 실제로 조작할 수 있는 별도 게임이 존재해 플레이어가 잠시 그 게임을 즐기는 중첩 구조다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-011046/index.html"},{"id":"MEJE-KW-011047","row_version":1,"title":"게임과 스포츠를 중심에 둔 일본 애니메이션·만화","original":"Gaming and Sports Anime & Manga","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"인물들이 경기나 놀이의 실력과 경쟁을 중심으로 성장하는 일본 애니메이션·만화의 이야기 유형이다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-011047/index.html"},{"id":"MEJE-KW-011048","row_version":1,"title":"함께 플레이하는 게임 동아리","original":"Gaming Clan","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"같은 게임을 정기적으로 즐기는 이용자들이 이름과 규칙을 공유하며 모이는 온라인 공동체다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-011048/index.html"},{"id":"MEJE-KW-011049","row_version":3,"title":"거리 갱단원의 전형적 재현","original":"Gangbangers","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 청년 갱단원을 범죄와 폭력, 낙서 등 몇 가지 행동으로 단순화해 그리는 재현 관습이다. 실제 지역·인종 집단의 속성으로 일반화하지 않는다. 거리 조직을 다루는 작품에서 한 구역의 우두머리는 거리 범죄를 지배하는 우두머리로 그려질 수 있다. 청년 집단에 대한 단순화된 재현은 여러 명이 약자를 괴롭히는 무리 지어 괴롭히는 인물들과 구별해야 한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011049/index.html"},{"id":"MEJE-KW-011050","row_version":2,"title":"갱단 가입을 위한 폭력 시험","original":"Gang Initiation Fight","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"범죄 조직이 새 구성원에게 폭력적 가입 의식을 요구하는 장면을 충성심 시험으로 그리는 재현 관습이다. 폭력을 정당화하는 기준은 아니다. 가입 의식을 장면으로 그릴 때는 거리 갱단원의 전형적 재현라는 집단 전형이 배경이 될 수 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011050/index.html"},{"id":"MEJE-KW-011051","row_version":2,"title":"달리는 차량에서 벌어지는 총격","original":"Gangland Drive-By","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"범죄 서사가 움직이는 차량에서 목표를 공격하는 총격을 빠르고 혼란스러운 위협 장면으로 그리는 관습이다. 도시 범죄 장면을 반복해 특정 도시 전체의 이미지로 확장하면 미국 도시를 범죄 천국으로 보다로 이어진다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011051/index.html"},{"id":"MEJE-KW-011052","row_version":2,"title":"거리 범죄를 지배하는 우두머리","original":"Gang Lord","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"도시의 한 구역을 자신의 영역처럼 다루고 범죄 조직원과 주민에게 영향력을 행사하는 적대자 인물형이다. 여러 범죄 조직이 맞서는 작품에서는 통일된 차림으로 구별되는 갱단로 소속을 눈에 띄게 구별하기도 한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-011052/index.html"},{"id":"MEJE-KW-011053","row_version":1,"title":"무리 지어 괴롭히는 인물들","original":"Gang of Bullies","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"한 명의 주도자와 그를 따르는 인물들이 수적 우위를 앞세워 약한 상대를 위협하는 집단형 가해자다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-011053/index.html"},{"id":"MEJE-KW-011054","row_version":1,"title":"통일된 차림으로 구별되는 갱단","original":"Gang of Hats","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"작품이 범죄 집단마다 색과 복장, 장비 같은 눈에 띄는 표식을 부여해 여러 조직을 쉽게 구별하게 하는 디자인이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-011054/index.html"},{"id":"MEJE-KW-011055","row_version":1,"title":"해적 테마로 꾸민 게임 구역","original":"Gangplank Galleon","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임 구간을 해적선뿐 아니라 항구·해안·해적 소품과 건축으로 꾸며 탐험 분위기와 장애물을 만드는 레벨 구성이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-011055/index.html"},{"id":"MEJE-KW-011056","row_version":1,"title":"거리 삶을 담은 갱스터 랩","original":"Gangsta Rap","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"도시의 가난과 폭력, 생존 경험을 강한 이야기와 리듬으로 표현해 온 힙합의 한 흐름이다. 작품이 이를 범죄의 찬양으로만 축소하는 관점과 구별한다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-011056/index.html"},{"id":"MEJE-KW-011057","row_version":1,"title":"옆으로 돌린 총의 화면 연출","original":"Gangsta Style","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 총을 옆으로 기울여 든 모습을 과시적이고 위협적인 이미지로 사용하는 시각 관습이다. 실제 집단을 대표하는 자세로 받아들이지 않는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011057/index.html"},{"id":"MEJE-KW-011058","row_version":1,"title":"미국 도시를 범죄 천국으로 보다","original":"Gangsterland","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 미국 대도시 전체를 갱단과 범죄자가 지배하는 듯 그려 현실의 다양한 삶을 가리는 과장된 도시 이미지다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011058/index.html"},{"id":"MEJE-KW-011059","row_version":1,"title":"컴퓨터 적들이 사람 플레이어만 노리다","original":"Gang Up on the Human","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 서로 적대해야 할 비인간 조작 세력들이 유독 사람 플레이어에게만 공격을 집중하는 인공지능 행동 관습이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-011059/index.html"},{"id":"MEJE-KW-011060","row_version":2,"title":"차고에서 연습하는 초보 밴드","original":"Garage Band","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"돈과 시설이 부족한 음악가들이 집의 차고를 연습실로 삼아 함께 노래와 공연을 준비하는 집단이다. 차고에서 시작한 밴드의 거친 음악이 차고 록로 불리기도 한다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-011060/index.html"},{"id":"MEJE-KW-011061","row_version":1,"title":"차고 록","original":"Garage Rock","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"거칠고 단순한 연주와 직접적인 에너지를 앞세운 록 음악의 한 흐름이다. 실제로 차고에서 연주했는지는 장르의 필수 조건이 아니다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-011061/index.html"},{"id":"MEJE-KW-011062","row_version":1,"title":"집 앞에서 여는 중고품 장터","original":"Garage Sale","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"가정이 쓰지 않는 물건을 집 앞이나 마당에 내놓고 이웃에게 판매하는 생활 행사다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-011062/index.html"},{"id":"MEJE-KW-011063","row_version":1,"title":"쓰레기통 속 은신","original":"Garbage Hideout","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 추적이나 시선을 피해 쓰레기통 또는 큰 폐기물 용기 안에 몸을 숨기는 이야기 장면이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-011063/index.html"},{"id":"MEJE-KW-011064","row_version":1,"title":"쓰레기가 모여 된 괴물","original":"Garbage Monster","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"버려진 물건들이 뭉쳐 몸을 이룬 존재를 불결함과 도시의 폐기물을 형상화한 괴물로 그리는 설정이다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-011064/index.html"},{"id":"MEJE-KW-011065","row_version":1,"title":"물건으로 치고받는 레슬러","original":"Garbage Wrestler","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"기술 경쟁보다 주변 물건을 쓰는 거친 공연과 위험한 연기로 자신의 캐릭터를 만드는 프로레슬러 인물형이다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-011065/index.html"},{"id":"MEJE-KW-011066","row_version":1,"title":"살아 있는 식물로 만든 옷","original":"Garden Garment","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"자라는 식물을 몸에 두르거나 의상으로 길러 내어 자연과 복식의 경계를 허무는 판타지 소품이다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-011066/index.html"},{"id":"MEJE-KW-011067","row_version":1,"title":"호스에서 갑자기 튄 물","original":"Garden-Hose Squirt Surprise","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"정원 호스에서 갑자기 튄 물을 인물이 맞아 놀라는 시각 개그. 다른 인물의 고의적인 장난이나 자신의 실수로 물줄기가 튈 수 있다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-011067/index.html"},{"id":"MEJE-KW-011068","row_version":1,"title":"정원 도구를 든 전투 장면","original":"Gardening-Variety Weapon","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 삽이나 갈퀴 같은 일상용 정원 도구를 뜻밖의 싸움 소품으로 사용해 즉흥성을 보여준다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011068/index.html"},{"id":"MEJE-KW-011069","row_version":2,"title":"에덴동산","original":"Garden of Eden","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"아브라함계 종교 전승에서 첫 인간이 살았다고 전해지는 낙원으로, 작품에서는 순수와 금기, 상실의 배경이 된다. 낙원의 정원과 반대로 위험한 식물이 지배하면 적대적인 식물의 정원이 된다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-011069/index.html"},{"id":"MEJE-KW-011070","row_version":2,"title":"적대적인 식물의 정원","original":"Garden of Evil","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"독을 품거나 움직이는 식물들이 모여 방문자를 위협하는 정원으로, 악역의 영역이나 위험한 세계의 일부가 된다. 위협으로 채운 정원과 달리 사랑이 피어나는 정원은 같은 공간을 관계의 배경으로 쓴다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-011070/index.html"},{"id":"MEJE-KW-011071","row_version":1,"title":"사랑이 피어나는 정원","original":"Garden of Love","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"정원을 두 인물이 만나고 마음을 나누는 공간으로 반복 사용해 자연의 성장과 사랑의 성장을 겹쳐 보이게 한다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-011071/index.html"},{"id":"MEJE-KW-011072","row_version":1,"title":"마시기 두려운 강한 술","original":"Gargle Blaster","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 한 잔만으로도 놀라운 취기나 기이한 반응을 부른다는 술을 과장해 희극적 소품으로 사용한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011072/index.html"},{"id":"MEJE-KW-011073","row_version":1,"title":"마늘을 몹시 싫어하는 인물","original":"Garlic Is Abhorrent","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"마늘의 냄새와 맛에 과장되게 반응하는 인물의 기호를 문화적 차이나 희극적 갈등으로 쓰는 표현이다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-011073/index.html"},{"id":"MEJE-KW-011074","row_version":1,"title":"이야기의 풍미를 더하는 요소","original":"Garnishing the Story","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"줄거리의 원인이나 필수 장치는 아니지만 인물과 세계에 작은 볼거리를 더해 작품을 풍성하게 만드는 요소다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-011074/index.html"},{"id":"MEJE-KW-011075","row_version":1,"title":"병력이 들어갈 수 있는 건물","original":"Garrisonable Structures","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"전략게임에서 보병을 건물 안에 배치할 수 있게 해 건물을 전투와 방어에 활용하는 규칙이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-011075/index.html"},{"id":"MEJE-KW-011076","row_version":1,"title":"말하는 몸의 혹","original":"Garrulous Growth","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"몸에 생긴 혹이나 피부 변화가 별도의 의식과 목소리를 지닌 존재처럼 움직여 불안과 기이함을 만드는 설정이다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-011076/index.html"},{"id":"MEJE-KW-011077","row_version":1,"title":"가스실","original":"Gas Chamber","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"작품에서 집단 학살이나 처형에 사용되는 밀폐된 살상 공간을 가리킨다. 독성 가스 또는 질식에 의한 죽음을 묘사할 수 있으며, 실제 홀로코스트의 학살 시설과 연결되는 역사적 공간이기도 하다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-011077/index.html"},{"id":"MEJE-KW-011078","row_version":1,"title":"가스통이 로켓처럼 날아가다","original":"Gas-Cylinder Rocket","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품에서 압축 가스 용기가 갑자기 튀어 올라 주변을 휩쓰는 장면으로 뜻밖의 사고와 위협을 만든다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011078/index.html"},{"id":"MEJE-KW-011079","row_version":1,"title":"가샤도쿠로","original":"Gashadokuro","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"일본 전승에서 원한과 죽음이 모여 나타난다고 여겨지는 거대한 해골 요괴로, 작품에서 집단적 비극을 형상화한다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-011079/index.html"},{"id":"MEJE-KW-011080","row_version":1,"title":"가스등 시대의 마법 판타지","original":"Gaslamp Fantasy","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"19세기를 중심으로 그 전후의 가스등 시대 분위기에 마법과 괴이한 존재를 결합하는 역사 판타지 하위 장르. 섭정시대처럼 19세기 전반을 닮은 배경도 포함한다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-011080/index.html"},{"id":"MEJE-KW-011081","row_version":2,"title":"가스 누출로 덮는 초자연적 사건","original":"Gas Leak Cover-Up","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"기관이 설명하기 어려운 사고와 목격담을 가스 사고라고 발표해 진짜 원인을 숨기는 서사 장치다. 사건의 진실을 평범한 사고로 덮는 설명은 목격자의 판단을 흔드는 상대의 현실 감각을 흔드는 조작와 만날 수 있다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-011081/index.html"},{"id":"MEJE-KW-011082","row_version":1,"title":"상대의 현실 감각을 흔드는 조작","original":"Gaslighting","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"한 인물이 사실과 기억을 거듭 부정하거나 주변 상황을 왜곡해 상대가 자신의 판단을 믿지 못하게 만드는 심리적 지배 관계다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-011082/index.html"},{"id":"MEJE-KW-011083","row_version":2,"title":"방독면과 긴 외투의 조합","original":"Gas Mask, Longcoat","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물에게 방독면과 긴 외투를 함께 입혀 종말 이후의 세계나 정체를 숨긴 전투원의 분위기를 만드는 의상 디자인이다. 방독면과 외투의 조합을 병사 집단에 반복 적용하면 방독면을 쓴 익명의 병사들이 된다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-011083/index.html"},{"id":"MEJE-KW-011084","row_version":1,"title":"방독면을 쓴 익명의 병사들","original":"Gas Mask Mooks","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"같은 방독면을 쓴 병사들이 얼굴을 구별할 수 없게 등장해 비인격적 집단의 위압감을 만드는 시각 표현이다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-011084/index.html"},{"id":"MEJE-KW-011085","row_version":1,"title":"휘발유를 뿌려 방화를 위협하거나 실행하다","original":"Gasoline Dousing","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"범죄 장면에서 인물이 가연성 액체를 끼얹고 불을 붙이겠다고 위협하거나 실제 방화를 저지르는 모습을 그리는 재현 관습. 피해의 위협과 잔혹성을 강조하는 서사 장치다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011085/index.html"},{"id":"MEJE-KW-011086","row_version":1,"title":"오래 둔 연료가 그대로 작동하다","original":"Gasoline Lasts Forever","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 오랜 세월 버려진 연료를 아무 문제 없이 곧바로 사용할 수 있는 것처럼 그려 세계의 시간을 단순화한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011086/index.html"},{"id":"MEJE-KW-011087","row_version":2,"title":"과장된 숨 들이마심","original":"Gasp!","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"놀란 인물이 숨을 갑자기 들이켜는 소리를 크게 내어 충격이나 희극적 반응을 알리는 연기·음향 관습. 한 사람이나 여러 사람이 반응할 수 있다. 놀람을 알리는 들숨이 죽은 인물의 귀환을 표현하면 되살아나며 크게 숨을 쉬다가 된다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-011087/index.html"},{"id":"MEJE-KW-011088","row_version":1,"title":"되살아나며 크게 숨을 쉬다","original":"Gasp of Life","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"죽었던 인물이 부활 직후 크게 숨을 들이마시는 모습으로 생명이 돌아왔음을 관객에게 알리는 장면이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-011088/index.html"},{"id":"MEJE-KW-011089","row_version":2,"title":"방귀와 트림이 잦은 인물","original":"Gasshole","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 인물의 잦은 방귀나 트림을 반복 농담과 성격 표지로 쓰는 재현 관습이다. 체형이나 도덕성과 연결하는 편견은 별개다. 반복되는 가스 농담은 음식을 원인으로 그리는 배에 가스를 찬다고 그린 음식과 이어질 수 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011089/index.html"},{"id":"MEJE-KW-011090","row_version":1,"title":"연료를 다른 곳으로 옮기는 장면","original":"Gas Siphoning","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"작품에서 차량이나 장비에 든 연료를 다른 용기로 옮기는 행동을 보여 주는 장면. 도난 사건으로 쓰일 수도 있지만 자기 소유 장비의 연료를 옮기는 상황도 포함한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-011090/index.html"},{"id":"MEJE-KW-011091","row_version":1,"title":"고립된 주유소의 공포","original":"Gas Station of Doom","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"외딴 길가의 주유소를 수상한 낯선 사람과 마주치거나 위협을 피해 갈 수 없는 공포의 장소로 사용한다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-011091/index.html"},{"id":"MEJE-KW-011092","row_version":2,"title":"배에 가스를 찬다고 그린 음식","original":"Gassy Gastronomy","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 특정 음식을 먹으면 곧 방귀나 트림이 나온다는 통념을 인물의 반응과 농담으로 활용하는 관습이다. 음식 때문에 생긴 불편을 심각한 병으로 오해하면 큰 병인 줄 알았던 복부 불편가 된다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011092/index.html"},{"id":"MEJE-KW-011093","row_version":1,"title":"큰 병인 줄 알았던 복부 불편","original":"Gassy Scare","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"인물이 복부의 불편함을 심각한 병으로 오인했다가 작품 속에서는 가스로 설명되며 안도나 민망함을 느끼는 반전이다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-011093/index.html"},{"id":"MEJE-KW-011094","row_version":2,"title":"입구를 지키는 수호자","original":"Gate Guardian","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"도시나 성역, 중요한 장소의 경계에서 방문자를 막거나 자격을 확인하는 인물 또는 존재형이다. 모든 지식의 문 앞에 수호자가 있다면 모든 지식이 모인 문가 접근을 막는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-011094/index.html"},{"id":"MEJE-KW-011095","row_version":2,"title":"출구가 보이지 않는 게임 도시","original":"Gateless Ghetto","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임이 도시의 일부만 만들고 바깥으로 이어지는 길은 보이지 않게 막아 플레이 공간의 경계를 숨기는 레벨 설계다. 도시 밖으로 나갈 출입구가 보이지 않는 설계는 입구를 지키는 수호자가 지키는 경계와 다르게 작동한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-011095/index.html"},{"id":"MEJE-KW-011096","row_version":1,"title":"모든 지식이 모인 문","original":"Gate of Truth","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"세상의 비밀에 닿을 수 있다는 문이나 경계가 존재하고, 그곳에 가려는 인물이 지식의 대가를 마주하는 세계관 설정이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-011096/index.html"},{"id":"MEJE-KW-011097","row_version":1,"title":"장르의 입문작이 된 시리즈","original":"Gateway Series","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"특정 작품이 처음 접한 관객에게 장르의 즐거움을 알려 다른 작품까지 찾아보게 하는 수용 현상이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-011097/index.html"},{"id":"MEJE-KW-011098","row_version":1,"title":"시간이 갈수록 강해지는 존재","original":"Gathering Steam","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물이나 세력이 초반에는 힘을 다 쓰지 못하지만 준비와 시간이 쌓일수록 본래의 위력을 낼 수 있게 되는 능력 조건이다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-011098/index.html"},{"id":"MEJE-KW-011099","row_version":1,"title":"회전 총열의 압도적 화력","original":"Gatling Good","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 여러 총열이 회전하는 큰 총을 강한 화력의 상징으로 내세우는 무기 연출 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011099/index.html"},{"id":"MEJE-KW-011100","row_version":1,"title":"가우초","original":"Gaucho","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"남아메리카 팜파스 지역의 목축과 말을 다루는 삶에서 나온 인물상으로, 작품에서는 독립심과 지역 정체성의 상징으로 쓰인다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-011100/index.html"},{"id":"MEJE-KW-011101","row_version":2,"title":"부드럽게 번지는 여성 촬영","original":"Gaussian Girl","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"작품이 여성 인물을 촬영할 때 화면을 유난히 흐리고 빛나게 만들어 아름다움과 낭만을 강조하는 시각 관습이다. 여성 인물을 흐리고 빛나게 찍는 방식은 누가 누구를 보도록 설계했는지 묻는 시각 매체의 시선와 연결된다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-011101/index.html"},{"id":"MEJE-KW-011102","row_version":1,"title":"성공 직전에 포기하다","original":"Gave Up Too Soon","aliases":[],"kind":"keyword","facet_id":"ML-F06","node_kind":null,"parent_id":null,"tag_path":["ML-F06"],"summary":"인물이 올바른 방법으로 목표에 가까워졌지만 마지막 순간에 지쳐 그만두어 눈앞의 성과를 놓치는 전개다.","accent":"#88734E","tab":"#9A6A55","facet":"서사 기능","bookmark":"분류축","entry_url":"cards/MEJE-KW-011102/index.html"},{"id":"MEJE-KW-011103","row_version":2,"title":"성소수자 수용을 가르치는 회차","original":"Gay Aesop","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 성소수자 인물을 소개하고 주변 인물의 편견을 갈등으로 삼아 수용의 교훈을 전달하는 재현 형식이다. 당사자의 삶을 교육용 장치로만 축소할 위험도 있다. 수용의 교훈을 전하려 성소수자 친구를 얕은 조력자에 머무르게 하면 주인공을 돕는 동성애자 친구 전형의 문제를 남긴다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011103/index.html"},{"id":"MEJE-KW-011104","row_version":1,"title":"들어간 곳이 게이 바임을 뒤늦게 알다","original":"Gay Bar Reveal","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"인물이 술집이나 클럽에 들어간 뒤 그곳이 게이 바라는 사실을 뒤늦게 깨닫는 반전을 당황이나 웃음의 장면으로 쓰는 재현 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011104/index.html"},{"id":"MEJE-KW-011105","row_version":2,"title":"주인공을 돕는 동성애자 친구 전형","original":"Gay Best Friend","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 동성애자 친구를 주인공의 패션·연애 조언과 희극적 분위기만 담당하게 하는 전형이다. 그 인물 자신의 삶과 관계가 지워질 수 있다. 성소수자 조연을 도구처럼 배치하는 전형은 동성애자 조연이 먼저 죽다와 함께 검토할 수 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011105/index.html"},{"id":"MEJE-KW-011106","row_version":1,"title":"성소수자 공동체가 모인 동네","original":"Gayborhood","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"성소수자 주민과 문화 공간이 모여 서로를 만나고 안전한 관계망을 형성해 온 도시의 한 구역이다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-011106/index.html"},{"id":"MEJE-KW-011107","row_version":2,"title":"동성애 암시로 태연함을 과시하다","original":"Gay Bravado","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"이성애자로 설정된 인물이 친구에게 동성애를 암시하는 말을 장난처럼 던지고 자신은 전혀 흔들리지 않는다고 보이려는 재현 관습이다. 동성애를 암시하는 농담 뒤에 불안해하며 부인하면 동성애처럼 보였다고 놀라는 인물과 맞닿는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011107/index.html"},{"id":"MEJE-KW-011108","row_version":1,"title":"보수적 신념을 지닌 동성애자","original":"Gay Conservative","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"성적 지향과 정치적 보수성을 함께 지닌 인물을 통해 주변의 단순한 기대나 내부 갈등을 드러낸다. 어느 집단도 단일한 정치 성향으로 묶이지 않는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-011108/index.html"},{"id":"MEJE-KW-011109","row_version":1,"title":"서부극의 동성애자 카우보이","original":"Gay Cowboy","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"서부 개척과 목장 문화의 외양을 지닌 남성 인물이 남성과 연애하거나 동성애 정체성을 지닌 모습으로 그려진다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-011109/index.html"},{"id":"MEJE-KW-011110","row_version":1,"title":"공공장소에서 상대를 찾는 성소수자","original":"Gay Cruising","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 남성 성소수자가 공공장소에서 합의 가능한 짧은 만남을 찾는 문화를 재현한다. 그 행위를 성소수자 전체의 특징으로 일반화하지 않는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011110/index.html"},{"id":"MEJE-KW-011111","row_version":1,"title":"남의 성적 지향을 알아본다는 감각","original":"Gaydar","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 인물의 말투나 몸짓만 보고 성적 지향을 알아맞힌다고 설정하는 관습이다. 실제 성적 지향은 외양만으로 신뢰성 있게 단정할 수 없다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011111/index.html"},{"id":"MEJE-KW-011112","row_version":1,"title":"동성애를 돌려 말하다","original":"Gay Euphemism","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 동성애를 직접 말하지 않고 우회적인 표현을 써 시대의 규범과 대화의 거리감을 드러내는 언어 관습이다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-011112/index.html"},{"id":"MEJE-KW-011113","row_version":2,"title":"한 사람만 흰 턱시도를 입은 결혼식","original":"Gay Groom in a White Tux","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"남성 동성 커플의 결혼식에서 한 사람에게 흰 예복, 다른 사람에게 검은 예복을 입혀 이성애 결혼의 신랑·신부 역할을 대응시키는 시각 관습이다. 동성 커플을 이성애 결혼의 역할로만 나누는 시선은 동성 관계를 한때의 단계로 치부하는 동성 연애를 한때의 단계로 치부하다와 다르게 나타나는 규범이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011113/index.html"},{"id":"MEJE-KW-011114","row_version":2,"title":"동성애자 조연이 먼저 죽다","original":"Gay Guy Dies First","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 동성애자 조연을 성격을 충분히 쌓기 전에 희생시켜 다른 인물의 위기를 강조하는 재현 관습이다. 성소수자 인물을 이르게 희생시키는 재현의 한 변형은 차별과 자기혐오에 따른 성소수자 자살 묘사이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011114/index.html"},{"id":"MEJE-KW-011115","row_version":1,"title":"인기 운동선수를 사랑하는 동성애 소년","original":"Gay Guy Seeks Popular Jock","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 소외된 동성애 소년과 인기 운동선수의 사랑을 신분과 평판의 차이를 넘는 연애 이야기로 반복해 그리는 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011115/index.html"},{"id":"MEJE-KW-011116","row_version":1,"title":"동성애처럼 보였다고 놀라는 인물","original":"Gay Moment","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"인물이 평범한 칭찬이나 행동을 동성애로 읽힐까 두려워하며 급히 이성애자임을 강조하는 희극적 재현이다. 동성애 자체를 수치로 전제할 위험이 있다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011116/index.html"},{"id":"MEJE-KW-011117","row_version":2,"title":"성적 지향을 둘러싼 고통의 반복","original":"Gayngst","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 성소수자 인물의 삶을 가족의 거부와 자기혐오, 사회적 편견에서 비롯된 고통으로만 그리는 재현 관습이다. 성소수자의 고통만 반복하는 서사가 자살로 끝나면 차별과 자기혐오에 따른 성소수자 자살 묘사로 이어진다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011117/index.html"},{"id":"MEJE-KW-011118","row_version":1,"title":"조직범죄에 속한 동성애자 인물","original":"Gayngster","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"성소수자 정체성과 범죄 조직의 역할을 함께 지닌 인물형이다. 성적 지향이 범죄의 원인이라는 뜻은 아니다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-011118/index.html"},{"id":"MEJE-KW-011119","row_version":1,"title":"차별과 자기혐오에 따른 성소수자 자살 묘사","original":"Gayngst-Induced Suicide","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 성소수자 인물의 차별 경험과 자기혐오를 자살과 연결해 그리는 재현 관습. 반드시 작품 전체의 결말일 필요는 없으며, 고통을 유일한 삶의 경로처럼 제시하는 한계를 함께 살펴야 한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011119/index.html"},{"id":"MEJE-KW-011120","row_version":2,"title":"같은 성별과 연애할 수 있는 선택지","original":"Gay Option","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임이 플레이어에게 동성 인물과도 관계를 맺을 수 있는 선택을 열어 두는 연애 규칙이다. 게임이 동성 연애를 지속 가능한 선택으로 열어 두는 방식은 동성 연애를 한때의 단계로 치부하다와 반대의 서사 방향이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-011120/index.html"},{"id":"MEJE-KW-011121","row_version":2,"title":"성소수자 등장에 대한 제작진의 후퇴","original":"Gay Panic","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"성소수자 인물에 대한 외부 반발이 생긴 뒤 제작진이 그 관계나 정체성을 흐리거나 삭제하는 제작 간섭의 결과다. 성소수자 묘사에 대한 제작 간섭은 관계를 임시 단계로 돌리는 동성 연애를 한때의 단계로 치부하다을 낳을 수 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-011121/index.html"},{"id":"MEJE-KW-011122","row_version":1,"title":"낭만적으로 이상화한 파리","original":"Gay Paree","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 파리를 예술과 연애가 가득한 도시로만 그려 실제 도시의 다양한 생활과 문제를 가리는 재현 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011122/index.html"},{"id":"MEJE-KW-011123","row_version":1,"title":"동성 연애를 한때의 단계로 치부하다","original":"Gay Romantic Phase","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 젊은 인물의 동성 관계를 잠깐의 혼란으로 다룬 뒤 이성 관계를 성숙한 결말처럼 제시하는 낡은 재현 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011123/index.html"},{"id":"MEJE-KW-011124","row_version":2,"title":"시각 매체의 시선","original":"Gaze","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"시각 매체에서 인물·카메라·편집·관객의 시선이 어떤 대상을 누구의 관점에서 보이게 하는지 살피는 개념. 화면의 선택과 배열이 인식 및 권력 관계를 형성하는 방식을 다룬다. 누구의 아름다움을 어떤 방식으로 보여주는지 묻는 관점에서 부드럽게 번지는 여성 촬영을 읽을 수 있다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-011124/index.html"},{"id":"MEJE-KW-011125","row_version":1,"title":"자동차 개조·복원 방송","original":"Gearhead Show","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04"],"summary":"낡은 자동차를 수리하거나 평범한 차를 특별하게 꾸미는 과정을 보여 주는 방송 형식이다. 작업 과정과 완성된 차의 변화가 볼거리가 된다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"분류축","entry_url":"cards/MEJE-KW-011125/index.html"},{"id":"MEJE-KW-011126","row_version":1,"title":"피할 수 없는 마법의 금기","original":"Geas","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"켈트 전승에서 나온 개념으로, 인물이 반드시 지키거나 어겨서는 안 되는 행동이 마법적 제약으로 부과되는 세계관 규칙이다. 본인의 의사와 무관하게 의무가 서사를 이끈다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-011126/index.html"},{"id":"MEJE-KW-011127","row_version":1,"title":"미완결 원작과 갈라지는 결말","original":"Gecko Ending","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"원작이 아직 끝나지 않았는데 각색 작품이 먼저 끝나야 할 때 제작진이 독자적인 완결을 만들어 이야기의 갈래를 나누는 방식이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-011127/index.html"},{"id":"MEJE-KW-011128","row_version":2,"title":"특정 취미에 깊이 빠진 팬","original":"Geek","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"한 분야의 지식과 작품을 깊이 즐기고 같은 관심사를 가진 사람들과 적극적으로 교류하는 인물형이다. 그 취향 자체가 일상과 말투의 일부가 된다. 관심 분야의 지식을 일상의 말에 끌어오면 동호인만 알아듣는 비유 같은 대화가 나타난다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-011128/index.html"},{"id":"MEJE-KW-011129","row_version":2,"title":"마르거나 뚱뚱하게만 그린 괴짜","original":"Geek Physiques","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 지적인 취미를 가진 인물의 몸을 운동과 거리가 먼 극단적인 체형으로만 그리는 외형 관습이다. 실제 취미와 체형의 관계를 설명하지 않는다. 외형을 획일화하는 관습은 취향까지 한데 묶는 괴짜라면 모두 좋아한다는 취향 목록과 함께 괴짜 인물을 단순화한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011129/index.html"},{"id":"MEJE-KW-011130","row_version":1,"title":"괴짜라면 모두 좋아한다는 취향 목록","original":"Geek Reference Pool","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 한 인물에게 괴짜라는 표시를 붙이면서 서로 다른 장르와 취미를 한꺼번에 좋아할 것이라 가정하는 재현 관습이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-011130/index.html"},{"id":"MEJE-KW-011131","row_version":2,"title":"동호인만 알아듣는 비유","original":"Geeky Analogy","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 익숙한 작품이나 취미의 장면을 끌어와 상황을 설명하지만 같은 관심사를 공유하지 않는 사람에게는 뜻이 잘 전해지지 않는다. 전문 지식을 드러내는 말이 호감의 계기가 되면 지식에 이끌리는 호감과 연결된다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-011131/index.html"},{"id":"MEJE-KW-011132","row_version":1,"title":"지식에 이끌리는 호감","original":"Geeky Turn-On","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"상대가 전문 지식을 능숙하게 말하거나 좋아하는 분야를 깊이 이해하는 모습을 보고 연애 감정이 커지는 관계 장면이다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-011132/index.html"},{"id":"MEJE-KW-011133","row_version":1,"title":"게이샤","original":"Geisha","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"전통 예술과 대화, 접객을 익혀 공연과 모임에서 활동하는 일본의 직업 문화다. 복식과 무대 예술의 역사적 맥락 속에서 살핀다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-011133/index.html"}]}.cards;